import React, { useState } from 'react';

const AuthButtons = () => {
    // Временный стейт для проверки залогинен ли пользователь
    const [isLoggedIn, setIsLoggedIn] = useState(false);

    // Временные данные пользователя (потом будут с API)
    const [user, setUser] = useState({
        name: 'Иван Петров',
        avatar: 'https://via.placeholder.com/40'
    });

    // Функции-заглушки (потом заменишь на реальные API вызовы)
    const handleLogin = () => {
        console.log('Переход на страницу логина');
        // Здесь будет вызов API или переход на страницу логина
    };

    const handleSignUp = () => {
        console.log('Переход на страницу регистрации');
        // Здесь будет вызов API или переход на страницу регистрации
    };

    const handleProfile = () => {
        console.log('Переход в профиль');
        // Здесь будет переход в профиль пользователя
    };

    const handleLogout = () => {
        setIsLoggedIn(false);
        console.log('Пользователь вышел');
        // Здесь будет API вызов для logout
    };

    // Временная кнопка для тестирования (убери потом)
    const toggleLogin = () => {
        setIsLoggedIn(!isLoggedIn);
    };

    return (
        <div className="auth-buttons">
            {/* Временная кнопка для тестирования */}
            <button onClick={toggleLogin} className="test-btn">
                {isLoggedIn ? 'Симуляция выхода' : 'Симуляция входа'}
            </button>

            {/* Основная логика */}
            {!isLoggedIn ? (
                // Если НЕ залогинен - показываем Login и Sign Up
                <div className="auth-buttons-container">
                    <button onClick={handleLogin} className="login-btn">
                        Log In
                    </button>
                    <button onClick={handleSignUp} className="signup-btn">
                        Sign Up
                    </button>
                </div>
            ) : (
                // Если залогинен - показываем профиль
                <div className="profile-container">
                    <div className="profile-info" onClick={handleProfile}>
                        <img src={user.avatar} alt="Avatar" className="avatar" />
                        <span className="user-name">{user.name}</span>
                    </div>
                    <button onClick={handleLogout} className="logout-btn">
                        Выйти
                    </button>
                </div>
            )}
        </div>
    );
};

export default AuthButtons;
